css=p.read_text()+r'''
/* Interaction psychology polish: stronger CTA hierarchy, app-like mobile surfaces, playful-but-premium motion. */
.btn.primary,.btn.gold{position:relative;overflow:hidden}.btn.primary:after,.btn.gold:after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 0%,rgba(255,255,255,.28) 45%,transparent 70%);transform:translateX(-120%)}.btn.primary:hover:after,.btn.gold:hover:after{animation:shine .9s ease}@keyframes shine{to{transform:translateX(120%)}}
.quick-card,.event-card,.pin,.opp,.announcement-card,.card{transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease}.quick-card:active,.event-card:active,.pin:active,.opp:active,.announcement-card:active{transform:scale(.985)}
.icon{animation:soft-bob 4.5s ease-in-out infinite}.quick-card:nth-child(2n) .icon{animation-delay:.7s}.quick-card:nth-child(3n) .icon{animation-delay:1.4s}@keyframes soft-bob{50%{transform:translateY(-4px) rotate(2deg)}}
.form select option[value=""]{display:none}.field-wrap{margin:0 0 18px}.field-wrap label{display:block;margin:0 0 8px;color:var(--navy);font-weight:900;font-size:1rem}.form-error{display:block;color:#b42318;font-weight:800;margin-top:6px}.btn-wide{width:100%;min-height:56px;font-size:1.05rem}.app-form input,.app-form select,.app-form textarea{width:100%;min-height:58px;border-radius:20px;border:1px solid var(--line);background:#fbfdff;padding:14px 16px;color:var(--navy);box-shadow:inset 0 1px 0 rgba(255,255,255,.8)}.app-form textarea{min-height:150px;resize:vertical}.app-form input:focus,.app-form select:focus,.app-form textarea:focus{outline:3px solid rgba(227,179,65,.28);border-color:var(--gold);background:#fff}
.newsletter-read{background:linear-gradient(180deg,#f6f9fd,#fff)}.newsletter-read-stack{display:grid;gap:26px}.newsletter-image-panel{background:#fff;border:1px solid var(--line);border-radius:30px;padding:14px;box-shadow:var(--shadow);max-width:920px;margin:0 auto;width:100%}.newsletter-image-panel img{width:100%;max-height:none;border-radius:22px;object-fit:contain}.newsletter-copy{max-width:920px;margin:0 auto}.newsletter-copy h1{font-size:clamp(2.1rem,5vw,4.2rem)}
.share-hero{background:radial-gradient(circle at 10% 5%,rgba(227,179,65,.18),transparent 26%),linear-gradient(180deg,#fff,#f6f9fd);padding:70px 0}.share-layout{display:grid;grid-template-columns:1.25fr .75fr;gap:24px;align-items:start}.share-copy h1{font-family:Poppins,Montserrat,Inter,sans-serif;color:var(--navy);font-size:clamp(2.4rem,5vw,4.8rem);line-height:1;letter-spacing:-.055em}.share-copy p{font-size:1.15rem;color:#42536d}.qr-card{text-align:center;position:sticky;top:94px}.qr-img{width:180px;max-width:100%;margin:12px auto;border-radius:18px;background:#fff;padding:10px;border:1px solid var(--line)}
.print-flyer-wrap{background:#f6f9fd}.print-flyer{max-width:820px;margin:auto;background:#fff;border:1px solid var(--line);border-radius:30px;box-shadow:var(--shadow);padding:28px}.print-mark{font-weight:900;color:var(--navy);letter-spacing:.12em;text-transform:uppercase;margin-bottom:18px}.print-flyer-image{width:100%;border-radius:24px;margin-bottom:24px;object-fit:contain}.print-flyer-copy h1{font-family:Poppins,Montserrat,Inter,sans-serif;color:var(--navy);font-size:clamp(2.2rem,6vw,4.8rem);line-height:1;letter-spacing:-.055em;margin:18px 0}.print-flyer-copy p{font-size:1.15rem;color:#253750}.print-share-row{display:flex;align-items:center;justify-content:space-between;gap:18px;border-top:1px dashed var(--line);margin-top:24px;padding-top:18px}.print-share-row span{font-size:.82rem;color:var(--muted);word-break:break-all}.print-actions{justify-content:center;margin-top:24px}
