print('css appended')"}

{"path":"/opt/data/HeRmEz/projects/cox-elementary-pta/static/js/script.js","content":"const menuButton=document.querySelector('.hamburger');const navLinks=document.querySelector('.nav-links');if(menuButton){menuButton.addEventListener('click',()=>{const open=navLinks.classList.toggle('open');document.body.classList.toggle('menu-open',open);menuButton.setAttribute('aria-expanded',String(open));});navLinks?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{navLinks.classList.remove('open');document.body.classList.remove('menu-open');menuButton.setAttribute('aria-expanded','false');}));}
const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.12,rootMargin:'0px 0px -30px'});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
document.querySelectorAll('.filter').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const f=btn.dataset.filter;document.querySelectorAll('[data-category]').forEach(card=>{card.style.display=(f==='all'||card.dataset.category===f)?'grid':'none'});}));
document.querySelectorAll('.btn,.quick-card,.event-card,.announcement-card').forEach(el=>{el.addEventListener('pointerdown',()=>el.classList.add('tap-active'));el.addEventListener('pointerup',()=>setTimeout(()=>el.classList.remove('tap-active'),140));el.addEventListener('pointerleave',()=>el.classList.remove('tap-active'));});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const hero=document.querySelector('.hero');window.addEventListener('scroll',()=>{if(!hero)return;const y=Math.min(32,window.scrollY*.05);hero.style.setProperty('--hero-drift',`${y}px`);},{passive:true});}
"}

