base='https://cox-elementary-pta.onrender.com'
for path in ['/newsletter/']:
    html=urllib.request.urlopen(base+path, timeout=30).read().decode('utf-8','ignore')
    imgs=re.findall(r'<img[^>]+src="([^"]+)"[^>]*alt="([^"]*)"', html)
    print(path, imgs[:10])
    for src, alt in imgs[:5]:
        if src.startswith('/'): url=base+src
        else: url=src
        try:
            r=urllib.request.urlopen(url, timeout=20)
            print(src, r.status, r.headers.get('content-type'))
        except Exception as e:
            print(src, type(e).__name__, e)"}

